    rgba(193, 222, 248, 0.714) 32.5px,
    rgba(183, 216, 247, 0.678) 48.5px,
    rgba(173, 211, 246, 0.651) 64.5px,
    rgba(163, 205, 245, 0.624) 80.5px,
    rgba(160, 204, 245, 0.616) 88.5px,
