    linear-gradient(90deg, rgba(0, 0, 0, 0.066) 0.5px, rgba(0, 0, 0, 0.031) 3.5px, rgba(0, 0, 0, 0.015) 5.5px, rgba(0, 0, 0, 0) 9px)
      left top / 9px calc(100% - 3px) no-repeat,
    linear-gradient(270deg, rgba(0, 0, 0, 0.066) 0.5px, rgba(0, 0, 0, 0.031) 3.5px, rgba(0, 0, 0, 0.015) 5.5px, rgba(0, 0, 0, 0) 9px)
      right top / 9px calc(100% - 3px) no-repeat,
    linear-gradient(
      #d8d8d8 0.5px,
      #9c9b9b 1.5px,
      #a8a7a7 5.5px,
      #b8b7b7 10.5px,
      #bebdbd 15.5px,
      #c1c0c0 20.5px,
      #c4c3c3 25.5px,
      #c6c5c5 30.5px,
      #c8c7c7 35px,
      #c8c7c6 calc(100% - 10.5px),
      #c5c4c4 calc(100% - 6.5px),
      #c3c2c2 calc(100% - 4px),
      #c6c5c5 calc(100% - 4px),
      #c6c5c5 calc(100% - 3px),
      #d8d8d7 calc(100% - 3px),
      #d8d8d7 calc(100% - 2px),
      #a9a9a9 calc(100% - 2px),
      #a9a9a9 calc(100% - 1px),
      #f2f2f1 calc(100% - 1px)
    ));

  background-origin: border-box;
}

/* Equal radii on all four corners, for a header used as a popup/toast cap. */
:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-page-header[data-corners="all"] {
