}

:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-app-menu-surface.nse-application-menu .nse-application-menu-list > .nse-control-list-item {
  display: flex;
  align-items: center;
  width: 100%;
  min-height: 48px;
  padding-right: 20px;
  padding-left: 20px;
  border: 0 solid transparent;
  border-top-width: 1px;
  border-bottom: 1px solid rgba(0, 0, 0, 0.2);
  border-image: none;
  box-shadow: 0 -1px 0 rgba(0, 0, 0, 0.36);
  background: transparent;
  color: #fff;
  text-shadow: 0 -1px 0 rgba(0, 0, 0, 0.55);
}

:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-app-menu-surface.nse-application-menu .nse-menu-shortcut,
