:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-app-menu-surface.nse-application-menu .nse-application-menu-list > .nse-control-list-item:not(.is-disabled):active {
  color: #fff;
  background: linear-gradient(#555, #888);
}

:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-app-menu-surface.nse-application-menu .nse-control-app-menu-inner > .nse-menu:hover,
:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-app-menu-surface.nse-application-menu .nse-control-app-menu-inner > .nse-menu:active {
  background: transparent;
