:scope[data-nse-theme="com.syndromatic.atmo"][data-mode="dark"] .nse-window-view.nse-window-view--popover:not([data-window-custom-chrome-active="true"]):not([data-window-chrome-mode="frameless"]) .nse-window__surface,
:scope[data-nse-theme="com.syndromatic.atmo"] [data-mode="dark"] .nse-window-view.nse-window-view--popover:not([data-window-custom-chrome-active="true"]):not([data-window-chrome-mode="frameless"]) .nse-window__surface {
