/* ============================================================================
   Keyboard focus: the push button's blue glow (2px ring, 2px halo, 9px bloom),
   drawn on each control's own shape instead of the shared structure's square
   outline. Master drew no focus at all on these; Heritage keeps the outline.
   ========================================================================= */
:scope[data-nse-theme="com.syndromatic.atmo"] {
  --nse-atmo-focus-ring:
    0 0 0 2px rgba(76, 164, 255, 0.95),
    0 0 0 4px rgba(108, 188, 255, 0.34),
    0 0 9px 4px rgba(62, 151, 247, 0.55);
}


:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-search-field:not([data-state="disabled"]):focus-within .nse-control-search-frame {
  border-radius: 999px;
  box-shadow: var(--nse-atmo-focus-ring);
}

/* The appearance accessibility rules otherwise outline the inner input box.
   Keep one focus indicator on the frame, including in contrast modes. */
:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-search-frame input[type="search"]:focus-visible {
  outline: none !important;
  box-shadow: none !important;
}

:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-search-field:not([data-state="disabled"]):focus-within .nse-control-search-frame:where([data-nse-contrast="high"] *) {
  outline: 3px solid var(--nse-contrast-accent);
  outline-offset: 2px;
  box-shadow: none;
}

:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-search-field:not([data-state="disabled"]):focus-within .nse-control-search-frame:where([data-nse-contrast="forced"] *) {
  outline: 2px solid Highlight;
  outline-offset: 2px;
  box-shadow: none;
}

@media (forced-colors: active) {
  :scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-search-field:not([data-state="disabled"]):focus-within .nse-control-search-frame {
    outline: 2px solid Highlight;
    outline-offset: 2px;
    box-shadow: none;
  }
}

:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-toggle:focus-visible,
:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-picker-button:focus-visible,
:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-radio:has(input:focus-visible),
:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-checkbox input:focus-visible + .nse-control-checkbox-art,
:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-slider input:focus-visible {
  outline: none;
}

/* Progress button: its capsule fills its 50px box. */
:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-progress-button:focus-visible {
  outline: none;
  border-radius: 25px;
  box-shadow: var(--nse-atmo-focus-ring);
}

/* Toggle: the 64×32 pill is the button's own box. */
:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-toggle:focus-visible {
  border-radius: 16px;
  box-shadow: var(--nse-atmo-focus-ring);
}

/* Picker: around its stroke ring (::before, r=10). */
:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-picker-button:focus-visible::before {
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.4), var(--nse-atmo-focus-ring);
}

/* Segment: the group clips anything outside a cell, so the ring runs just
   inside the focused cell's rim, over its fill. */
:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-radio:has(input:focus-visible)::after {
  box-shadow:
    inset 0 0 0 2px rgba(76, 164, 255, 0.95),
    inset 0 0 6px 2px rgba(62, 151, 247, 0.5);
}

/* Checkbox: around the well (x0 y2, 25×25.5, r=4 in the 33×28 cell), not the
   cell the check overflows into. */
:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-checkbox input:focus-visible + .nse-control-checkbox-art {
  position: relative;
}

:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-checkbox input:focus-visible + .nse-control-checkbox-art::after {
  content: "";
  position: absolute;
  left: 0;
  top: 2px;
  width: 25px;
  height: 25.5px;
  border-radius: 4px;
  box-shadow: var(--nse-atmo-focus-ring);
  pointer-events: none;
}

/* Slider: around the knob (27px, centred in the 50px thumb cell). */
:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-slider:has(input:focus-visible) .nse-control-slider-thumb-visual::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 49.4%;
  width: 54%;
  height: 54%;
  border-radius: 50%;
  box-shadow: var(--nse-atmo-focus-ring);
  transform: translate(-50%, -50%);
  pointer-events: none;
}

/* ============================================================================
   Calendar (Atmo-designed). The well is the text field's language (white,
   #a6a6a6/#bfbfbf hairline, soft top inner shadow, white underline); nav
   buttons are small light-tone pills; a selected day is the glossy blue of
   the slider knob and the selected toolbar button, with white type; hover is
   a faint blue wash. Dark mode swaps the well for the Preferences slate.
   ========================================================================= */
:scope[data-nse-theme="com.syndromatic.atmo"],
:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-surface-ink="light"] {
  --nse-atmo-cal-well: linear-gradient(#e9e9e9 0, #f6f6f6 3px, #ffffff 8px, #ffffff calc(100% - 2px), #f7f7f7 100%);
  --nse-atmo-cal-stroke: #a6a6a6 #bfbfbf #c4c4c4;
  --nse-atmo-cal-under: 0 1px 0 rgba(255, 255, 255, 0.75);
  --nse-atmo-cal-ink: #25303c;
  --nse-atmo-cal-title: #1d2a37;
  --nse-atmo-cal-weekday: #7a8390;
  --nse-atmo-cal-adjacent: #a6acb4;
  --nse-atmo-cal-rule: rgba(0, 0, 0, 0.09);
  --nse-atmo-cal-rule-light: rgba(255, 255, 255, 0.9);
  --nse-atmo-cal-hover: rgba(74, 136, 200, 0.13);
  --nse-atmo-cal-nav-fill: linear-gradient(#fdfdfd, #e3e3e3);
  --nse-atmo-cal-nav-pressed: linear-gradient(#cfcfcf, #e0e0e0);
  --nse-atmo-cal-nav-stroke: rgba(0, 0, 0, 0.26) rgba(0, 0, 0, 0.3) rgba(0, 0, 0, 0.4);
  --nse-atmo-cal-nav-glyph: #4a5563;
  --nse-atmo-cal-dot: #3d86d6;
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"] {
  color: var(--nse-atmo-cal-ink);
  border: 1px solid;
  border-color: var(--nse-atmo-cal-stroke);
  background: var(--nse-atmo-cal-well) padding-box;
  box-shadow: var(--nse-atmo-cal-under);
}

:scope[data-nse-theme="com.syndromatic.atmo"][data-mode="dark"],
:scope[data-nse-theme="com.syndromatic.atmo"] [data-mode="dark"] {
  --nse-atmo-cal-well: linear-gradient(#20252c 0, #292f37 4px, #2c323a 12px, #2a3038 100%);
  --nse-atmo-cal-stroke: rgba(0, 0, 0, 0.75) rgba(0, 0, 0, 0.6) rgba(0, 0, 0, 0.5);
  --nse-atmo-cal-under: 0 1px 0 rgba(255, 255, 255, 0.08);
  --nse-atmo-cal-ink: #e4e8ee;
  --nse-atmo-cal-title: #f1f4f8;
  --nse-atmo-cal-weekday: #8d97a4;
  --nse-atmo-cal-adjacent: #626b77;
  --nse-atmo-cal-rule: rgba(0, 0, 0, 0.45);
  --nse-atmo-cal-rule-light: rgba(255, 255, 255, 0.06);
  --nse-atmo-cal-hover: rgba(120, 170, 230, 0.18);
  --nse-atmo-cal-nav-fill: linear-gradient(#4a525c, #353c45);
  --nse-atmo-cal-nav-pressed: linear-gradient(#2a3037, #383f48);
  --nse-atmo-cal-nav-stroke: rgba(0, 0, 0, 0.6) rgba(0, 0, 0, 0.65) rgba(0, 0, 0, 0.75);
  --nse-atmo-cal-nav-glyph: #d4dae2;
  --nse-atmo-cal-dot: #7bb6ee;
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"] > [data-nse-part="header"] > h2 {
  color: var(--nse-atmo-cal-title);
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"] > [data-nse-part="header"] > button {
  color: var(--nse-atmo-cal-nav-glyph);
  border: 1px solid;
  border-color: var(--nse-atmo-cal-nav-stroke);
  background: var(--nse-atmo-cal-nav-fill) padding-box;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.55), 0 1px 1px rgba(0, 0, 0, 0.12);
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"] > [data-nse-part="header"] > button:active {
  background: var(--nse-atmo-cal-nav-pressed) padding-box;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.25);
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"] [role="row"]:first-child {
  border-block-end: 1px solid var(--nse-atmo-cal-rule);
  box-shadow: 0 1px 0 var(--nse-atmo-cal-rule-light);
  margin-block-end: 3px;
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"] [role="columnheader"] {
  color: var(--nse-atmo-cal-weekday);
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"] [data-nse-part="day"] {
  color: var(--nse-atmo-cal-ink);
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"] [data-nse-part="day"][data-state="adjacent"] {
  color: var(--nse-atmo-cal-adjacent);
  font-weight: 500;
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"] [data-nse-part="day"]:not(:disabled):not([data-state="selected"]):hover {
  background: var(--nse-atmo-cal-hover);
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"] [data-nse-part="day"][data-state="selected"] {
  color: #fff;
  border-color: #2f6aa8 #2a62a0 #1f4f86;
  background: linear-gradient(#8ec3f3 0, #68a8ea 45%, #4a90dd 55%, #3f86d4 100%) padding-box;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.45), 0 1px 1px rgba(0, 0, 0, 0.18);
  text-shadow: 0 -1px 0 rgba(20, 60, 110, 0.55);
  font-weight: 800;
}

/* Today: a hairline ring and blue numeral, under any selection paint. */
:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"] [data-nse-part="day"][data-today]:not([data-state="selected"]) {
  border-color: var(--nse-atmo-cal-today-ring);
  color: var(--nse-atmo-cal-today-ink);
  font-weight: 800;
}

/* Ranges: the endpoints keep the glossy pill, rounded on their outer side
   only; days between sit on a pale band of the same blue with ordinary
   ink. The band bridges the grid's 1px gaps and rounds at week edges. */
:scope[data-nse-theme="com.syndromatic.atmo"],
:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-surface-ink="light"] {
  --nse-atmo-cal-band: rgba(74, 144, 221, 0.2);
}

:scope[data-nse-theme="com.syndromatic.atmo"][data-mode="dark"],
:scope[data-nse-theme="com.syndromatic.atmo"] [data-mode="dark"] {
  --nse-atmo-cal-band: rgba(110, 170, 235, 0.24);
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"] [data-nse-part="day"][data-range-position="middle"] {
  color: var(--nse-atmo-cal-ink);
  border-color: transparent;
  border-radius: 0;
  background: var(--nse-atmo-cal-band);
  box-shadow: 1px 0 0 var(--nse-atmo-cal-band);
  text-shadow: none;
  font-weight: 700;
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"] [data-nse-part="day"][data-range-position="start"] {
  border-start-end-radius: 0;
  border-end-end-radius: 0;
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"] [data-nse-part="day"][data-range-position="end"] {
  border-start-start-radius: 0;
  border-end-start-radius: 0;
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"] [role="row"] > span:first-child > [data-nse-part="day"]:is([data-range-position="middle"], [data-range-position="end"]) {
  border-start-start-radius: 7px;
  border-end-start-radius: 7px;
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"] [role="row"] > span:last-child > [data-nse-part="day"]:is([data-range-position="middle"], [data-range-position="start"]) {
  border-start-end-radius: 7px;
  border-end-end-radius: 7px;
  box-shadow: none;
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"][dir="rtl"] [data-nse-part="day"][data-range-position="middle"] {
  box-shadow: -1px 0 0 var(--nse-atmo-cal-band);
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"] [data-nse-part="event-indicator"] {
  background: var(--nse-atmo-cal-dot);
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"] [data-state="selected"] [data-nse-part="event-indicator"] {
