}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"] :is([data-nse-part="day"], [data-nse-part="header"] > button):focus-visible {
  z-index: 1;
  outline: none;
  box-shadow: 0 0 0 2px rgba(76, 164, 255, 0.95), 0 0 6px 2px rgba(62, 151, 247, 0.5);
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="calendar"] [data-nse-part="day"][data-state="selected"]:focus-visible {
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.45), 0 0 0 2px rgba(76, 164, 255, 0.95), 0 0 6px 2px rgba(62, 151, 247, 0.5);
}

/* ============================================================================
   Clock (Atmo-designed). The dial is a silver dome in the checkbox well's
   greys inside a dark bezel ring, with hour and minute ticks; hands are
   graphite, the second hand is the Atmo selection blue, and the centre cap
   is the slider's glossy blue knob in miniature. The numeric fields are the
   text field's white pill. Dark mode turns the dome to slate.
   ========================================================================= */
:scope[data-nse-theme="com.syndromatic.atmo"],
:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-surface-ink="light"] {
  --nse-atmo-clock-bezel: linear-gradient(#9da1a7, #6c7076);
  --nse-atmo-clock-dome: radial-gradient(circle at 50% 30%, #ffffff 0, #f6f7f8 38%, #e3e5e9 78%, #d3d6db 100%);
  --nse-atmo-clock-tick: rgba(43, 52, 64, 0.72);
  --nse-atmo-clock-tick-minor: rgba(43, 52, 64, 0.22);
  --nse-atmo-clock-hand: #2b3440;
  --nse-atmo-clock-label: #4f5a67;
  --nse-atmo-clock-field-fill: linear-gradient(#e6e6e6 0, #f7f7f7 3px, #ffffff 7px);
  --nse-atmo-clock-field-stroke: #9a9a9a #bfbfbf #c6c6c6;
  --nse-atmo-clock-field-ink: #1d2a37;
}

:scope[data-nse-theme="com.syndromatic.atmo"][data-mode="dark"],
:scope[data-nse-theme="com.syndromatic.atmo"] [data-mode="dark"] {
  --nse-atmo-clock-bezel: linear-gradient(#5a616b, #1f242a);
  --nse-atmo-clock-dome: radial-gradient(circle at 50% 30%, #56606c 0, #414953 40%, #30363e 80%, #262b31 100%);
  --nse-atmo-clock-tick: rgba(232, 236, 242, 0.8);
  --nse-atmo-clock-tick-minor: rgba(232, 236, 242, 0.22);
  --nse-atmo-clock-hand: #eef1f5;
  --nse-atmo-clock-label: #aab3bf;
  --nse-atmo-clock-field-fill: linear-gradient(#1d2127 0, #262b32 4px, #2b3139 10px);
  --nse-atmo-clock-field-stroke: rgba(0, 0, 0, 0.8) rgba(0, 0, 0, 0.6) rgba(0, 0, 0, 0.5);
  --nse-atmo-clock-field-ink: #eef1f5;
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="clock"] > [data-nse-part="face"] {
  border: 1px solid rgba(0, 0, 0, 0.55);
  background: var(--nse-atmo-clock-bezel);
