    repeating-conic-gradient(from -1.2deg, var(--nse-atmo-clock-tick) 0 2.4deg, transparent 2.4deg 30deg),
    repeating-conic-gradient(from -0.5deg, var(--nse-atmo-clock-tick-minor) 0 1deg, transparent 1deg 6deg);
  -webkit-mask: radial-gradient(circle, transparent 0 calc(50% - 9px), #000 calc(50% - 9px) calc(50% - 3px), transparent calc(50% - 3px));
  mask: radial-gradient(circle, transparent 0 calc(50% - 9px), #000 calc(50% - 9px) calc(50% - 3px), transparent calc(50% - 3px));
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="clock"] > [data-nse-part="face"]::after {
  content: "";
  position: absolute;
  inset: 5px;
  z-index: -2;
  border-radius: 50%;
  background: var(--nse-atmo-clock-dome);
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.28), inset 0 -1px 0 rgba(255, 255, 255, 0.35);
  pointer-events: none;
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="clock"] [data-nse-part="hour-hand"],
