  border: 1px solid #2a5f99;
  box-sizing: border-box;
  background: radial-gradient(circle at 50% 30%, #b9dcfa 0, #6aa9e9 55%, #3f86d4 100%);
  box-shadow: 0 1px 1px rgba(0, 0, 0, 0.3);
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="clock"] > [data-nse-part="face"]:focus-visible {
  outline: none;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.35), var(--nse-atmo-focus-ring);
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="clock"] > [data-nse-part="numeric"] > label {
  color: var(--nse-atmo-clock-label);
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="clock"] > [data-nse-part="numeric"] input {
  color: var(--nse-atmo-clock-field-ink);
  border: 1px solid;
  border-color: var(--nse-atmo-clock-field-stroke);
  background: var(--nse-atmo-clock-field-fill) padding-box;
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.6);
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="clock"] > [data-nse-part="numeric"] input:focus-visible {
