}

:scope[data-nse-theme="com.syndromatic.atmo"] :is([data-nse-control="combo-box"], [data-nse-control="token-field"], [data-nse-control="secure-text-field"]) > input:not([type="hidden"]) {
  flex: 1 1 120px;
  min-inline-size: 0;
  block-size: 34px;
  margin: 0;
  padding: 0;
  border: 0;
