:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="token-field"] [data-nse-part="token"] > button:focus-visible {
  outline: none;
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="secure-text-field"] > button {
  flex: 0 0 auto;
