  border-start-start-radius: 13px;
  border-end-start-radius: 13px;
}
:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="segmented-control"] > :first-child > button:first-child::after,
:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="segmented-control"] > button:first-child::after {
  inset-inline-start: 2px;
  border-inline-start-color: var(--nse-atmo-rg-ring-s);
  border-start-start-radius: 11px;
  border-end-start-radius: 11px;
}

/* Last cell (the overflow button, or the last segment's last button). */
:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="segmented-control"] > button:is(:last-child, :has(+ input[type="hidden"]:last-child)), :scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="segmented-control"] > [data-nse-part="segment"]:is(:last-child, :has(+ input[type="hidden"]:last-child)) > button:last-child {
  padding-inline-end: 18px;
}
:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="segmented-control"] > button:is(:last-child, :has(+ input[type="hidden"]:last-child))::before, :scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="segmented-control"] > [data-nse-part="segment"]:is(:last-child, :has(+ input[type="hidden"]:last-child)) > button:last-child::before {
