  border-start-end-radius: 13px;
  border-end-end-radius: 13px;
}
:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="segmented-control"] > button:is(:last-child, :has(+ input[type="hidden"]:last-child))::after, :scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="segmented-control"] > [data-nse-part="segment"]:is(:last-child, :has(+ input[type="hidden"]:last-child)) > button:last-child::after {
  inset-inline-end: 2px;
  border-inline-end-color: var(--nse-atmo-rg-ring-s);
  border-start-end-radius: 11px;
  border-end-end-radius: 11px;
}

/* Selected segment (and an open menu/overflow): the black ink. */
:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="segmented-control"] button:is([aria-pressed="true"], [aria-expanded="true"]) {
