}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="segmented-control"] button:active:not(:disabled)::after {
  background: var(--nse-atmo-rg-sel) padding-box;
  opacity: 0.8;
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="segmented-control"] button:focus-visible {
  outline: none;
  z-index: 1;
}
:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="segmented-control"] button:focus-visible::before {
