/* ============================================================================
   Progress indicator and level indicator on the Atmo progress material: the
   11px measured track and fill twins (--nse-atmo-pg-track / -fill, sliced
   0 6 0 6). A bar reads its percentage from --nse-control-progress and puts
   the status caption beside it; indeterminate sweeps a third-width fill
   (still under reduced motion); circular is a ring and spinner a turning
   arc at data-size. The level indicator is the same track with its fill in
   blue (normal), amber (warning) or red (critical).
   ========================================================================= */
:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="progress-indicator"][data-variant="bar"] {
  display: grid;
  grid-template-columns: minmax(80px, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-inline-size: 0;
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="progress-indicator"][data-variant="bar"] > [data-nse-part="track"] {
  position: relative;
  display: block;
  block-size: 11px;
  border: solid transparent;
  border-width: 0 6px;
  border-image: var(--nse-atmo-pg-track) 0 6 0 6 fill stretch;
  overflow: hidden;
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="progress-indicator"][data-variant="bar"] [data-nse-part="fill"] {
  position: absolute;
  inset-block: 0;
  inset-inline-start: -6px;
  inline-size: calc(var(--nse-control-progress, 0%) + 12px * var(--nse-control-progress-on, 1));
  min-inline-size: 12px;
  max-inline-size: calc(100% + 12px);
  box-sizing: border-box;
  border: solid transparent;
  border-width: 0 6px;
  border-image: var(--nse-atmo-pg-fill) 0 6 0 6 fill stretch;
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="progress-indicator"][data-variant="bar"][data-state="indeterminate"] [data-nse-part="fill"] {
  inline-size: 34%;
  animation: com-syndromatic-atmo-nse-atmo-progress-sweep 1.4s ease-in-out infinite alternate;
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="progress-indicator"][data-variant="bar"][data-state="indeterminate"][data-motion="static"] [data-nse-part="fill"] {
  inset-inline-start: 33%;
  animation: none;
}

@keyframes com-syndromatic-atmo-nse-atmo-progress-sweep {
  from { inset-inline-start: -6px; }
  to { inset-inline-start: calc(66% + 6px); }
}

@media (prefers-reduced-motion: reduce) {
  :scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="progress-indicator"][data-variant="bar"][data-state="indeterminate"] [data-nse-part="fill"] {
    inset-inline-start: 33%;
    animation: none;
  }
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="progress-indicator"] > [data-nse-part="status"] {
  color: var(--nse-atmo-label-ink, #314255);
  font-size: 12px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="progress-indicator"]:is([data-variant="circular"], [data-variant="spinner"]) {
  --nse-atmo-progress-size: 16px;
  display: inline-grid;
  place-items: center;
}
:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="progress-indicator"][data-size="32"] { --nse-atmo-progress-size: 32px; }
:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="progress-indicator"][data-size="64"] { --nse-atmo-progress-size: 64px; }

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="progress-indicator"]:is([data-variant="circular"], [data-variant="spinner"]) > [data-nse-part="track"] {
  display: block;
  inline-size: var(--nse-atmo-progress-size);
  block-size: var(--nse-atmo-progress-size);
  border-radius: 50%;
  background: conic-gradient(#5b8db8 var(--nse-control-progress, 0%), rgba(0, 0, 0, 0.14) 0);
  -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - max(2px, var(--nse-atmo-progress-size) / 7)), #000 0);
  mask: radial-gradient(farthest-side, transparent calc(100% - max(2px, var(--nse-atmo-progress-size) / 7)), #000 0);
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="progress-indicator"]:is([data-variant="spinner"], [data-state="indeterminate"]):not([data-variant="bar"]) > [data-nse-part="track"] {
  background: conic-gradient(rgba(91, 141, 184, 0) 0, #5b8db8 75%, rgba(91, 141, 184, 0) 0);
