}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="progress-indicator"][data-motion="static"] > [data-nse-part="track"] {
  animation: none;
}

@keyframes com-syndromatic-atmo-nse-atmo-progress-turn {
  to { transform: rotate(1turn); }
}

:scope[data-nse-theme="com.syndromatic.atmo"] [data-nse-control="progress-indicator"]:is([data-variant="circular"], [data-variant="spinner"]) > [data-nse-part="status"] {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
}

:scope[data-nse-theme="com.syndromatic.atmo"] meter[data-nse-control="level-indicator"] {
  display: block;
  min-block-size: 11px;
  box-sizing: border-box;
  inline-size: 160px;
  max-inline-size: 100%;
  block-size: 11px;
  border: solid transparent;
  border-width: 0 6px;
  border-image: var(--nse-atmo-pg-track) 0 6 0 6 fill stretch;
  --nse-atmo-level-tint: none;
}

:scope[data-nse-theme="com.syndromatic.atmo"] meter[data-nse-control="level-indicator"][data-state="warning"] { --nse-atmo-level-tint: hue-rotate(185deg) saturate(1.9) brightness(1.08); }
:scope[data-nse-theme="com.syndromatic.atmo"] meter[data-nse-control="level-indicator"][data-state="critical"] { --nse-atmo-level-tint: hue-rotate(150deg) saturate(2.4) brightness(0.92); }

:scope[data-nse-theme="com.syndromatic.atmo"] meter[data-nse-control="level-indicator"]::-webkit-meter-inner-element,
:scope[data-nse-theme="com.syndromatic.atmo"] meter[data-nse-control="level-indicator"]::-webkit-meter-bar {
  margin-inline: -6px;
  background: transparent;
  border: 0;
}

:scope[data-nse-theme="com.syndromatic.atmo"] meter[data-nse-control="level-indicator"]::-webkit-meter-optimum-value,
:scope[data-nse-theme="com.syndromatic.atmo"] meter[data-nse-control="level-indicator"]::-webkit-meter-suboptimum-value,
:scope[data-nse-theme="com.syndromatic.atmo"] meter[data-nse-control="level-indicator"]::-webkit-meter-even-less-good-value {
