  content: "";
  grid-row: 2;
  grid-column: 1;
  align-self: stretch;
  box-sizing: border-box;
  border: 0 solid transparent;
  border-width: 0 6px;
  border-image: var(--nse-atmo-pg-track) 0 6 0 6 fill stretch;
}

:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-progress-item-fill {
  position: static;
  grid-row: 2;
  grid-column: 1;
  align-self: stretch;
  justify-self: start;
  box-sizing: border-box;
  width: var(--nse-control-progress, 0%);
  min-width: 12px;
  border: 0 solid transparent;
  border-width: 0 6px;
  border-image: var(--nse-atmo-pg-fill) 0 6 0 6 fill stretch;
}

