  visibility: hidden;
}

:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-progress-item-label {
  grid-row: 1;
  grid-column: 1;
  padding: 0;
}

:scope[data-nse-theme="com.syndromatic.atmo"] .nse-control-progress-item[data-variant="pill"] {
