:scope[data-nse-theme="com.syndromatic.atmo"] .nse-extended-prev-next-button.nse-extended-tool-button.nse-control-button[data-direction="next"] { background-position: 0 -150px; }
:scope[data-nse-theme="com.syndromatic.atmo"] .nse-extended-prev-next-button.nse-extended-tool-button.nse-control-button[data-direction="next"]:is(:active, [data-press-active="true"]):not(:disabled) { background-position: 0 -200px; }
:scope[data-nse-theme="com.syndromatic.atmo"] .nse-extended-prev-next-button.nse-extended-tool-button.nse-control-button[data-direction="next"]:disabled { background-position: 0 -250px; }

:scope[data-nse-theme="com.syndromatic.atmo"] .nse-extended-prev-next-button.nse-extended-tool-button.nse-control-button:disabled {
